package dev.veltraph.client.greenhouse;

import com.google.gson.Gson;
import dev.veltraph.client.gui.MenuSnapshot;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static dev.veltraph.client.greenhouse.GreenhouseModel.*;

class GreenhouseObservationsTest {
    @Test void offlineDeltaNeverGrantsReadinessAndGrowthClockNeverTreatedAsEpoch(){var p=new Plant("Wheat",PlantState.GROWING,WaterState.WATERED,1,new Clock(ClockKind.GROWTH_CYCLE,2,"native"),Clock.unknown(),Clock.unknown(),"state","diagnostic");var s=GreenhouseRuntimeTest.snapshot(10,1,p,Map.of("tool",1));var scheduler=new GreenhouseCareScheduler();assertTrue(scheduler.evaluate(s,100000,5000,OptionalLong.of(100000)).stream().allMatch(r->r.care()==GreenhouseCareScheduler.Care.INSPECT));assertEquals(GreenhouseCareScheduler.Care.WAIT,scheduler.evaluate(s,11,5000,OptionalLong.of(100000)).getFirst().care());}
    @Test void elapsedWaterDeadlineRequiresRefreshRatherThanAssumingDry(){var p=new Plant("Wheat",PlantState.GROWING,WaterState.WATERED,1,Clock.unknown(),new Clock(ClockKind.SERVER_EPOCH,100,"native"),Clock.unknown(),"state","diagnostic");var s=GreenhouseRuntimeTest.snapshot(10,1,p,Map.of("tool",1));assertEquals(GreenhouseCareScheduler.Care.INSPECT,new GreenhouseCareScheduler().evaluate(s,11,5000,OptionalLong.of(101)).getFirst().care());}
    @Test void storeIsScopedAndRejectsOutOfOrderObservations(){var store=new Store();var s=GreenhouseRuntimeTest.snapshot(10,2,GreenhouseRuntimeTest.READY,Map.of("tool",1));store.observe(s);store.observe(GreenhouseRuntimeTest.snapshot(9,1,GreenhouseRuntimeTest.EMPTY,Map.of()));assertEquals(PlantState.HARVEST_READY,store.get(s.context(),GreenhouseRuntimeTest.CELL).orElseThrow().plant().state());assertEquals(Knowledge.UNKNOWN,store.knowledge(new Context("other","greenhouse-bed","world"),GreenhouseRuntimeTest.CELL,11,5000));assertEquals(Knowledge.STALE,store.knowledge(s.context(),GreenhouseRuntimeTest.CELL,5011,5000));}
    @Test void historicalDustgrainCountsCannotValidateCurrentCombination(){var c=new GreenhouseCombinations();assertFalse(c.DUSTGRAIN.current());assertEquals(GreenhouseCombinations.Result.UNKNOWN_RECIPE,c.validate("Dustgrain",GreenhouseRuntimeTest.snapshot(10,1,GreenhouseRuntimeTest.READY,Map.of()),null,10,5000).result());}
    @Test void exactGuideCountsAndOffsetsHaveNativeProvenance(){var binding=new GreenhouseGuide.Binding("Fixture Guide","Recipe","minecraft:paper","Crop: ","Profile: fixture","Plot: bed",Map.of("Wheat","Wheat count: "),"Offset: ");var menu=new MenuSnapshot(4,"Fixture Guide",List.of(new MenuSnapshot.Slot(0,"Recipe",List.of("Profile: fixture","Plot: bed","Crop: Dustgrain","Wheat count: 2","Offset: 1 0 0","Offset: -1 0 0"),false,"minecraft:paper")),7);var recipe=GreenhouseGuide.read(menu,binding,GreenhouseRuntimeTest.CONTEXT,10).orElseThrow();assertEquals(Map.of("Wheat",2),recipe.ingredients());assertTrue(recipe.source().contains("revision=7"));assertEquals(2,recipe.offsets().size());var conflicting=new MenuSnapshot(4,"Fixture Guide",List.of(new MenuSnapshot.Slot(0,"Recipe",List.of("Profile: fixture","Plot: bed","Crop: Dustgrain","Wheat count: 2","Wheat count: 4"),false,"minecraft:paper")));assertTrue(GreenhouseGuide.read(conflicting,binding,GreenhouseRuntimeTest.CONTEXT,10).isEmpty());}
    @Test void exactDiagnosticBindingRejectsAmbiguousMaturityAndPlayerInventory(){var cell=new Cell(0,70,0);var cb=new GreenhouseBindings.CellBinding(cell,"Plant","minecraft:paper","Cell 0 70 0","Crop: ","Empty","Growing","Ready","Dry","Watered","Stage: ","Water epoch: ","Growth cycle: ","Decay epoch: ",cell);var b=new GreenhouseBindings("Fixture Diagnostics","fixture","bed","Profile: fixture","Plot: bed","diagnostic-tool",3,List.of(cb));assertNotNull(GreenhouseBindings.parse(new Gson().toJson(b)));var lore=List.of("Profile: fixture","Plot: bed","Cell 0 70 0","Crop: Wheat","Growing","Dry","Stage: 1","Growth cycle: 40");var m=new MenuSnapshot(2,"Fixture Diagnostics",List.of(new MenuSnapshot.Slot(0,"Plant",lore,false,"minecraft:paper")));var p=b.read(m,Map.of(cell,"wheat[age=1]")).orElseThrow().get(cell);assertEquals(ClockKind.GROWTH_CYCLE,p.nextGrowth().kind());assertFalse(p.waterExpiry().known());assertTrue(b.read(new MenuSnapshot(2,"Fixture Diagnostics",List.of(new MenuSnapshot.Slot(0,"Plant",lore,true,"minecraft:paper"))),Map.of(cell,"wheat[age=1]")).isEmpty());var conflicting=new ArrayList<>(lore);conflicting.add("Ready");assertTrue(b.read(new MenuSnapshot(2,"Fixture Diagnostics",List.of(new MenuSnapshot.Slot(0,"Plant",conflicting,false,"minecraft:paper"))),Map.of(cell,"wheat[age=1]")).isEmpty());}
    @Test void complexCellKeysAndObservationEpochRoundtrip(){var s=GreenhouseRuntimeTest.snapshot(10,2,GreenhouseRuntimeTest.READY,Map.of("tool",1));var gson=new com.google.gson.GsonBuilder().enableComplexMapKeySerialization().create();assertEquals(s,gson.fromJson(gson.toJson(s),Snapshot.class));}
    @Test void officialIdentityCatalogHasNoTimerOrRecipeInference(){var catalog=GreenhouseIdentityCatalog.bundled();assertEquals(45,catalog.entries().size());assertEquals(40,catalog.entries().stream().filter(e->"MUTATION".equals(e.category())).count());assertTrue(catalog.diagnostic().contains("unknown"));}
    @Test void missingObservationAndTimerRemainUnknown(){assertEquals(GreenhouseCareScheduler.Care.INSPECT,new GreenhouseCareScheduler().evaluate(null,10,100,OptionalLong.empty()).getFirst().care());assertFalse(Clock.unknown().known());}
}
